//! 🧪️ Own IFC2x3 import/export admission, unchanged official input and original logical validation observations.
use super::{decode_ifc2x3,encode_ifc2x3,validate_ifc2x3_exchange_with};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🔣️.json")).expect("neutral boundary vectors")}
fn frame(base:&serde_json::Value,case:&serde_json::Value)->String{let part=|key:&str,fallback:&str|case.get(key).and_then(|value|value.as_str()).or_else(||base.get(fallback).and_then(|value|value.as_str())).unwrap_or("");format!("ISO-10303-21;HEADER;FILE_DESCRIPTION({});FILE_NAME({});FILE_SCHEMA({});{}ENDSEC;DATA;{}ENDSEC;{}{}",part("description","description"),part("nameAttributes","name"),part("schema","schema"),part("headerSuffix","unused"),part("data","data"),case.get("terminator").and_then(|value|value.as_str()).unwrap_or("END-ISO-10303-21;"),part("suffix","unused"))}
#[test]
fn neutral_import_and_export_boundaries(){let fixture=fixture();for case in fixture["cases"].as_array().unwrap(){let source=frame(&fixture["base"],case);let result=decode_ifc2x3(source.as_bytes());let expected=case["accepted"].as_bool().unwrap();assert_eq!(result.is_ok(),expected,"{}: {result:?}",case["name"]);if let Ok(snapshot)=result{let bytes=encode_ifc2x3(&snapshot).expect("export valid exchange");assert_eq!(decode_ifc2x3(&bytes).unwrap(),snapshot);}}}
#[test]
fn direct_export_cannot_bypass_strict_import_policy(){let fixture=fixture();let original=decode_ifc2x3(frame(&fixture["base"],&fixture["cases"][0]).as_bytes()).unwrap();let mut duplicate=original.clone();duplicate.document.instances.push(duplicate.document.instances[0].clone());assert!(encode_ifc2x3(&duplicate).is_err());let mut zero=original.clone();zero.document.instances[0].id=0;assert!(encode_ifc2x3(&zero).is_err());let mut dangling=original.clone();dangling.document.instances[0].entities[0].1=vec![semio_s_artifact_stdio_contract::part21::Part21Value::Ref(999)];assert!(encode_ifc2x3(&dangling).is_err());let mut mixed=original.clone();mixed.document.header.file_schema=vec![semio_s_artifact_stdio_contract::part21::Part21Value::List(vec![semio_s_artifact_stdio_contract::part21::Part21Value::Str("IFC2X3".into()),semio_s_artifact_stdio_contract::part21::Part21Value::Str("IFC4".into())])];assert!(encode_ifc2x3(&mixed).is_err());}
#[test]
fn borrowed_validation_uses_original_observer_and_preserves_exact_input(){let fixture=fixture();let original=decode_ifc2x3(frame(&fixture["base"],&fixture["cases"][0]).as_bytes()).unwrap();let before=original.clone();let mut observations=0;assert!(validate_ifc2x3_exchange_with(&original,&mut |_|{observations+=1;Err("original cancellation".into())}).is_err());assert_eq!(observations,1);assert_eq!(original,before);let mut work=0;assert!(validate_ifc2x3_exchange_with(&original,&mut |_|{work+=1;if work>fixture["limits"]["work"].as_u64().unwrap(){Err("original work limit".into())}else{Ok(())}}).is_err());}
#[test]
fn unchanged_official_ifc2x3_architecture_roundtrips(){let original=decode_ifc2x3(include_bytes!("../../../🧪️tests/🧫️fixtures/📐️geometry/official-architecture.ifc")).expect("unchanged official source");assert_eq!(original.document.instances.len(),2046);assert_eq!(decode_ifc2x3(&encode_ifc2x3(&original).unwrap()).unwrap(),original);}

#[test]
fn owned_edm_metadata_roundtrips_and_refuses_token_injection(){let fixture=fixture();let mut snapshot=decode_ifc2x3(frame(&fixture["base"],&fixture["cases"][0]).as_bytes()).unwrap();let neutral:serde_json::Value=serde_json::from_str(include_str!("../../🏭️preamble/🧪️tests/🔣️.json")).unwrap();let value=|key:&str|neutral["values"][key].as_str().unwrap().to_string();snapshot.edm_preamble=Some(semio_s_artifact_stdio_ifc_2x3_base_model::standards::v2x3::subsets::base::schema::snapshot::Ifc2x3EdmPreamble{producer:value("producer"),module:value("module"),creation_date:value("creationDate"),host:value("host"),database:value("database"),database_version:value("databaseVersion"),database_creation_date:value("databaseCreationDate"),schema:value("schema"),model:value("model"),model_creation_date:value("modelCreationDate"),header_model:value("headerModel"),header_model_creation_date:value("headerModelCreationDate"),user:value("user"),group:value("group"),license:value("license"),options:value("options")});assert_eq!(decode_ifc2x3(&encode_ifc2x3(&snapshot).unwrap()).unwrap(),snapshot);for invalid in neutral["invalidValues"].as_array().unwrap(){let mut malformed=snapshot.clone();malformed.edm_preamble.as_mut().unwrap().producer=invalid.as_str().unwrap().into();assert!(encode_ifc2x3(&malformed).is_err());}}
#[test]
fn native_metadata_observer_only_sees_actual_comments(){let fixture=fixture();let neutral:serde_json::Value=serde_json::from_str(include_str!("../../🏭️preamble/🧪️tests/🔣️.json")).unwrap();let mut banner=String::from("/******************************************************************************************\n");for label in neutral["labels"].as_array().unwrap(){banner.push_str(&format!("* {} Value\n",label[1].as_str().unwrap()));}banner.push_str("******************************************************************************************/");let source=frame(&fixture["base"],&fixture["cases"][0]);let actual=source.replacen("HEADER;",&format!("HEADER;{banner}"),1);assert!(decode_ifc2x3(actual.as_bytes()).unwrap().edm_preamble.is_some());let duplicate=source.replacen("HEADER;",&format!("HEADER;{banner}{banner}"),1);assert!(decode_ifc2x3(duplicate.as_bytes()).is_err());let incomplete=actual.replace("* Module: Value\n","");assert!(decode_ifc2x3(incomplete.as_bytes()).is_err());let mut quoted=fixture["cases"][0].clone();quoted["data"]=format!("#1=IFCFOO('{banner}');").into();assert!(decode_ifc2x3(frame(&fixture["base"],&quoted).as_bytes()).unwrap().edm_preamble.is_none());}
